import java.util.*;

class Solution {
    public TreeNode insertIntoBST(TreeNode root, int key) {
        TreeNode node = new TreeNode(key);
        if (root == null) return node; // empty tree: new node is the root
        TreeNode cur = root;
        while (true) {
            if (key < cur.val) {
                if (cur.left == null) { cur.left = node; break; } // empty spot found
                cur = cur.left;
            } else {
                if (cur.right == null) { cur.right = node; break; }
                cur = cur.right;
            }
        }
        return root;
    }
}

