class Solution:
    def insertIntoBST(self, root: Optional[TreeNode], key: int) -> Optional[TreeNode]:
        if not root: return TreeNode(key)
        cur = root
        while True:
            if key < cur.val:
                if not cur.left: cur.left = TreeNode(key); break
                cur = cur.left
            else:
                if not cur.right: cur.right = TreeNode(key); break
                cur = cur.right
        return root

